    // Optimized by checking divisibility up to sqrt(n)
    private static boolean isPrime(long number) {
        if (number <= 1) {
            return false;
        }
        if (number <= 3) {
            return true;
        }
        if (number % 2 == 0 || number % 3 == 0) {
            return false;
        }
        for (long i = 5; i * i <= number; i += 6) {
            if (number % i == 0 || number % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }

    // Method to generate the nth prime Fibonacci number
    public static long getNthPrimeFibonacci(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer.");
        }

        long a = 0; // First Fibonacci number
        long b = 1; // Second Fibonacci number
        int count = 0; // Counter for prime Fibonacci numbers

        while (true) {
            long current = a;
            if (isPrime(current)) {
                count++;
                if (count == n) {
                    return current;
                }
            }
            // Move to the next Fibonacci number
            long next = a + b;
            a = b;
            b = next;
        }
    }

    // Main method to handle input and output
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter the value of n: ");
        while (!scanner.hasNextInt()) {
            System.out.print("Invalid input. Please enter an integer: ");
            scanner.next();
        }
        int n = scanner.nextInt();
        scanner.close();

        try {
            long result = getNthPrimeFibonacci(n);
            System.out.println("The " + n + "th prime Fibonacci number is: " + result);
        } catch (IllegalArgumentException e) {
            System.out.println("Error: " + e.getMessage());
        }
    }
}
