import java.util.*;

public class PairSumFinder {
    public static void main(String[] args) {
        // Example usage
        int[] array = {1, 1, 2, 2, 3, 3};
        int target = 5;
        List<int[]> result = findPairsWithSum(array, target);

        System.out.println("Pairs with sum " + target + ":");
        for (int[] pair : result) {
            System.out.println("(" + pair[0] + ", " + pair[1] + ")");
        }
    }

    public static List<int[]> findPairsWithSum(int[] array, int target) {
        // Handle null or empty array
        if (array == null || array.length == 0) {
            return new ArrayList<>();
        }

        List<int[]> result = new ArrayList<>();
        Set<Integer> used = new HashSet<>();
        Map<Integer, Integer> valueToIndex = new HashMap<>();

        // First pass: populate the map with values and their indices
        for (int i = 0; i < array.length; i++) {
            valueToIndex.put(array[i], i);
        }

        // Second pass: find pairs
        for (int i = 0; i < array.length; i++) {
            int current = array[i];
            int complement = target - current;

            // Check if complement exists and is not used
            if (valueToIndex.containsKey(complement) && !used.contains(i)) {
                int complementIndex = valueToIndex.get(complement);

                // Ensure the complement is not the same element (to avoid duplicates)
                if (complementIndex != i) {
                    // Check if the complement has not been used
                    if (!used.contains(complementIndex)) {
                        // Add the pair to the result
                        result.add(new int[]{current, complement});
                        // Mark both elements as used
                        used.add(i);
                        used.add(complementIndex);
                    }
                }
            }
        }

        return result;
    }
}
